def countHappy(n):
    LIM = 6 * 81 + 1

    def s(x):
        t = 0
        while x:
            x, d = divmod(x, 10)
            t += d * d
        return t

    happy = [False] * (LIM + 1)
    for v in range(1, LIM + 1):
        slow, fast = v, s(v)
        while fast != 1 and slow != fast:
            slow = s(slow)
            fast = s(s(fast))
        happy[v] = fast == 1
    sq = [0] * (n + 1)
    count = 0
    for x in range(1, n + 1):
        sq[x] = sq[x // 10] + (x % 10) ** 2
        if happy[sq[x]]:
            count += 1
    return count
